examples.query:
query ProductMetafields($ownerId: ID!) {
  product(id: $ownerId) {
    metafields(first: 3) {
      edges {
        node {
          namespace
          key
          value
        }
      }
    }
  }
}

query ProductMetafieldTranslations($productId: ID!) {
  product(id: $productId) {
    metafields(first: 3) {
      edges {
        node {
          namespace
          key
          value
          translations(locale: "fr") {
            key
            value
          }
        }
      }
    }
  }
}

query {
  product(id: "gid://shopify/Product/49527214") {
    title
    publishedInCA: publishedInContext(context: {country: CA})
    publishedInGB: publishedInContext(context: {country: GB})
    publishedInUS: publishedInContext(context: {country: US})
  }
}

query ProductImageCount($productId: ID!) {
  product(id: $productId) {
    mediaCount {
      count
    }
  }
}

query ProductMetafield($namespace: String!, $key: String!, $ownerId: ID!) {
  product(id: $ownerId) {
    linerMaterial: metafield(namespace: $namespace, key: $key) {
      value
    }
  }
}

query ProductShow($id: ID!) {
  product(id: $id) {
    publishedOnCurrentPublication
    id
    createdAt
    updatedAt
    descriptionHtml
    handle
    productType
    title
    vendor
    tags
    publishedAt
    variants(first: 10) {
      nodes {
        id
      }
    }
    images(first: 10) {
      nodes {
        id
        height
        width
        url
      }
    }
  }
}

query {
  node(id: "gid://shopify/Product/108828309") {
    id
    ... on Product {
      title
    }
  }
}

query {
  product(id: "gid://shopify/Product/108828309") {
    collections(first: 5) {
      edges {
        node {
          handle
        }
      }
    }
    createdAt
    defaultCursor
    description
    descriptionHtml
    featuredMedia {
      id
    }
    feedback {
      details {
        messages {
          message
        }
      }
    }
    giftCardTemplateSuffix
    handle
    hasOnlyDefaultVariant
    hasOutOfStockVariants
    id
    media(first: 5) {
      edges {
        node {
          id
        }
      }
    }
    inCollection(id: "gid://shopify/Collection/1007901140")
    isGiftCard
    legacyResourceId
    metafields(first: 5) {
      edges {
        node {
          id
        }
      }
    }
    onlineStorePreviewUrl
    onlineStoreUrl
    options {
      name
    }
    priceRangeV2 {
      maxVariantPrice {
        amount
      }
      minVariantPrice {
        amount
      }
    }
    productType
    resourcePublicationsCount {
      count
    }
    availablePublicationsCount {
      count
    }
    publishedAt
    resourcePublications(first: 5) {
      edges {
        node {
          isPublished
        }
      }
    }
    resourcePublicationOnCurrentPublication {
      publication {
        id
      }
      publishDate
      isPublished
    }
    seo {
      title
    }
    tags
    templateSuffix
    title
    totalInventory
    tracksInventory
    unpublishedPublications(first: 5) {
      edges {
        node {
          id
        }
      }
    }
    updatedAt
    variants(first: 5) {
      edges {
        node {
          displayName
        }
      }
    }
    variantsCount {
      count
    }
    vendor
  }
}

query GetProduct($id: ID!) {
  product(id: $id) {
    id
    title
    variants(first: 10) {
      nodes {
        id
        title
      }
    }
    collections(first: 10) {
      nodes {
        id
        title
      }
    }
  }
}

query {
  product(id: "gid://shopify/Product/108828309") {
    title
    media(first: 5) {
      edges {
        node {
          ...fieldsForMediaTypes
        }
      }
    }
  }
}

fragment fieldsForMediaTypes on Media {
  alt
  mediaContentType
  preview {
    image {
      id
      altText
      url
    }
  }
  status
  ... on Video {
    id
    sources {
      format
      height
      mimeType
      url
      width
    }
    originalSource {
      format
      height
      mimeType
      url
      width
    }
  }
  ... on ExternalVideo {
    id
    host
    originUrl
  }
  ... on Model3d {
    sources {
      format
      mimeType
      url
    }
    originalSource {
      format
      mimeType
      url
    }
  }
  ... on MediaImage {
    id
    image {
      altText
      url
    }
  }
}

query CollectionsForProduct($productId: ID!) {
  product(id: $productId) {
    collections(first: 10) {
      nodes {
        id
        title
      }
    }
  }
}

query ProductImageList($productId: ID!) {
  product(id: $productId) {
    media(first: 10, query: "media_type:IMAGE", sortKey: POSITION) {
      nodes {
        id
        alt
        ... on MediaImage {
          createdAt
          image {
            width
            height
            url
          }
        }
      }
      pageInfo {
        startCursor
        endCursor
      }
    }
  }
}

query TranslationsAndLocalizations {
  product(id: "gid://shopify/Product/273955669") {
    title
    descriptionHtml
    translations(locale: "fr") {
      key
      value
    }
    localizations: translations(locale: "fr", marketId: "gid://shopify/Market/249692835") {
      key
      value
    }
  }
}

query {
  product(id: "gid://shopify/Product/108828309") {
    title
    variants(first: 10) {
      edges {
        node {
          selectedOptions {
            name
            value
          }
          media(first: 10) {
            edges {
              node {
                alt
                mediaContentType
                status
                __typename
                ... on MediaImage {
                  id
                  preview {
                    image {
                      originalSrc
                    }
                  }
                  __typename
                }
              }
            }
          }
        }
      }
    }
  }
}
